const wm_source_anim_program_t *wm_source_anim_program_find(uint8_t r,const char*l){size_t i;if(!l)return 0;for(i=0;i<sizeof(all_programs)/sizeof(all_programs[0]);++i){const wm_source_anim_program_t*p=all_programs[i];if((p->roster_id==r||p->roster_id==255u)&&!strcmp(p->label,l))return p;}return 0;}
const wm_source_anim_table_t *wm_source_anim_table_by_id(uint16_t id){return id<(uint16_t)(sizeof(all_tables)/sizeof(all_tables[0]))?all_tables[id]:0;}
const wm_source_anim_table_t *wm_source_anim_table_find(const char*f,const char*l){size_t i;if(!l)return 0;for(i=0;i<sizeof(all_tables)/sizeof(all_tables[0]);++i){const wm_source_anim_table_t*t=all_tables[i];if(!strcmp(t->label,l)&&(!f||!strcmp(t->source_file,f)))return t;}if(f)for(i=0;i<sizeof(all_tables)/sizeof(all_tables[0]);++i)if(!strcmp(all_tables[i]->label,l))return all_tables[i];return 0;}
size_t wm_source_anim_program_count(void){return sizeof(all_programs)/sizeof(all_programs[0]);}
size_t wm_source_anim_table_count(void){return sizeof(all_tables)/sizeof(all_tables[0]);}
